import{_ as a,o as t,c as r,N as o}from"./chunks/framework.11ad0a06.js";const u=JSON.parse('{"title":"Preload","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/preload.md","lastUpdated":1795525255000}'),s={name:"en/guide/preload.md"};function i(c,e,l,d,p,n){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="preload" tabindex="-1">Preload <a class="header-anchor" href="#preload" aria-label="Permalink to &quot;Preload&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Preloading dramatically improves the first-screen load time of sub-apps.</p></div><h2 id="preloading" tabindex="-1">Preloading <a class="header-anchor" href="#preloading" aria-label="Permalink to &quot;Preloading&quot;">​</a></h2><p>Preloading uses <code>requestIdleCallback</code> during browser idle time to fetch a sub-app&#39;s static assets from the network into memory ahead of time. See <a href="/doc/en/api/preloadApp.html">preloadApp</a> for details.</p><h2 id="pre-execution" tabindex="-1">Pre-execution <a class="header-anchor" href="#pre-execution" aria-label="Permalink to &quot;Pre-execution&quot;">​</a></h2><p>Pre-execution renders the sub-app in advance during browser idle time, further reducing perceived startup latency.</p><p>Simply set <a href="/doc/en/api/preloadApp.html#exec">exec</a> to <code>true</code> in <code>preloadApp</code>.</p><p>Because pre-executing a sub-app could block the main app&#39;s main thread, Wujie uses a <a href="https://github.com/acdlite/react-fiber-architecture" target="_blank" rel="noreferrer">React Fiber</a>-inspired execution mode to yield back to the browser between scripts. See <a href="/doc/en/api/startApp.html#fiber">fiber</a> for details.</p><h2 id="clearing-the-assets-cache" tabindex="-1">Clearing the Assets Cache <a class="header-anchor" href="#clearing-the-assets-cache" aria-label="Permalink to &quot;Clearing the Assets Cache&quot;">​</a></h2><p>Wujie caches sub-app HTML, JS, and CSS at the module level to speed up repeat loads. If a sub-app&#39;s static assets have been updated or you need to force a fresh fetch, call <a href="/doc/en/api/clearAssetsCache.html">clearAssetsCache</a> to invalidate the cache globally or for specific hosts.</p>',10)])])}const f=a(s,[["render",i]]);export{u as __pageData,f as default};
